-- ================================================================
-- GamerTavern / NanashiCollectibles — CURRENT DATABASE SCHEMA
-- ================================================================
-- Fresh-install script: creates the complete CURRENT GamerTavern
-- schema from an empty database. Generated by concatenating
-- schema/001_core_auth.sql through schema/008_platform_ops.sql, in
-- dependency order — do not edit this file directly; edit the
-- numbered file in schema/ and regenerate this one.
--
-- This is the ONLY schema file you need to run for a fresh install.
-- Do not also run Database/archive/All.sql (the old, superseded
-- design) or any individual schema/*.sql file separately.
--
-- MySQL 5.7+ / MariaDB 10.3+ compatible. utf8mb4 / utf8mb4_unicode_ci
-- throughout. No CHECK constraints (see schema/ file headers for why);
-- every rule that would have been a CHECK is enforced in backend
-- application code instead.
--
-- NAMING CONVENTION (2026-09-14 uppercase migration): every table,
-- column, index, and constraint name is UPPER_SNAKE_CASE. Data VALUES
-- (status strings in DEFAULT clauses, etc.) are untouched — some
-- domains use lowercase values ('active', 'draft') and some use
-- uppercase values ('PENDING', 'ACTIVE') exactly as they did before
-- this migration; that's an application-level convention, not a
-- schema-identifier one, and was deliberately left alone.
--
-- lower_case_table_names=0 on the production MariaDB (Linux/cPanel)
-- host — table names ARE case-sensitive there. Backend SQL must use
-- these exact identifiers; see Database/migrations/0002_*.sql for the
-- migration that converts an existing lowercase installation.
--
-- Generated: 2026-09-14, from the GamerTavern database cleanup +
-- uppercase-identifier migration.
--
-- Contains NO data — no fake merchants, no test users, no sample
-- products. For reference/master data, run seeds/reference.sql
-- afterward. For throwaway development data, run seeds/development.sql
-- afterward (development databases only — see the warning in that file).
--
-- Select your GamerTavern database before running this script.
-- USE `your_gamertavern_schema`;
-- ================================================================


-- ================================================================
-- ================================================================
-- 001 — CORE AUTH
-- ================================================================
-- Single identity system for the whole platform: customer, merchant
-- staff, and admin are ALL rows in `USERS`, distinguished only by
-- `USERS.ROLE` and (for MERCHANTS) a `MERCHANT_USERS` membership —
-- see 004_merchants.sql. There is no separate admin_users/sessions
-- table. Canonical REST auth lives in Backend/routes/api/auth.routes.js.
-- ================================================================

CREATE TABLE USERS (
  ID                 INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  ROLE               VARCHAR(20)   NOT NULL DEFAULT 'user',      -- 'user' | 'vendor' | 'admin' — app-validated, not ENUM
  NAME               VARCHAR(100)  NOT NULL,
  EMAIL              VARCHAR(100)  NOT NULL,
  PHONE              VARCHAR(20)   NULL,
  PASSWORD_HASH      VARCHAR(255)  NOT NULL,                     -- bcrypt hash
  PROFILE_ICON       VARCHAR(255)  NULL,
  STATUS             VARCHAR(20)   NOT NULL DEFAULT 'active',    -- 'active' | 'suspended' | 'deleted' — soft delete, never hard-delete a user with real history
  EMAIL_VERIFIED_AT  TIMESTAMP     NULL,
  LAST_LOGIN_AT      TIMESTAMP     NULL,
  CREATED_AT         TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UPDATED_AT         TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY UQ_USERS_EMAIL (EMAIL),
  UNIQUE KEY UQ_USERS_PHONE (PHONE),
  INDEX IDX_USERS_ROLE (ROLE),
  INDEX IDX_USERS_STATUS (STATUS)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE PASSWORD_RESET_TOKENS (
  ID          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  USER_ID     INT UNSIGNED NOT NULL,
  TOKEN_HASH  CHAR(64)     NOT NULL,                             -- SHA-256 of the raw token; raw token is never stored
  EXPIRES_AT  DATETIME     NOT NULL,
  USED_AT     TIMESTAMP    NULL,                                 -- NULL = unused; set when the token is consumed
  CREATED_AT  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT FK_PASSWORD_RESET_TOKENS_USER
    FOREIGN KEY (USER_ID) REFERENCES USERS(ID) ON DELETE CASCADE,
  UNIQUE KEY UQ_PASSWORD_RESET_TOKENS_TOKEN_HASH (TOKEN_HASH),
  INDEX IDX_PASSWORD_RESET_TOKENS_USER (USER_ID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- ================================================================
-- 002 — REFERENCE / LOOKUP DATA
-- ================================================================
-- No foreign keys out; referenced by later modules. Seed data for
-- these (except `COUNTRIES`, which has none yet) lives in
-- Database/seeds/reference.sql — safe to run against production.
-- ================================================================

CREATE TABLE COUNTRIES (
  ID            INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  NAME          VARCHAR(100) NOT NULL,
  ISO_CODE      CHAR(2)      NOT NULL,                           -- ISO 3166-1 alpha-2, e.g. 'BN'
  CALLING_CODE  VARCHAR(10)  NOT NULL,                           -- e.g. '+673'
  FLAG          VARCHAR(10)  NULL,                                -- FLAG emoji, e.g. '🇧🇳'
  CREATED_AT    TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UPDATED_AT    TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY UQ_COUNTRIES_ISO_CODE (ISO_CODE),
  INDEX IDX_COUNTRIES_CALLING_CODE (CALLING_CODE)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- No seed data yet — empty live today; add via seeds/reference.sql when needed.

CREATE TABLE PRODUCT_CATEGORIES (
  ID           INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  NAME         VARCHAR(100) NOT NULL,
  SLUG         VARCHAR(120) NOT NULL,
  DESCRIPTION  TEXT NULL,
  CREATED_AT   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UPDATED_AT   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY UQ_PRODUCT_CATEGORIES_SLUG (SLUG)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE TCG_GAMES (
  ID          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  NAME        VARCHAR(100) NOT NULL,
  SLUG        VARCHAR(120) NOT NULL,
  STATUS      VARCHAR(20)  NOT NULL DEFAULT 'active',            -- 'active' | 'coming_soon'
  CREATED_AT  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UPDATED_AT  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY UQ_TCG_GAMES_SLUG (SLUG)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE ESPORTS_GAMES (
  ID          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  NAME        VARCHAR(100) NOT NULL,
  SLUG        VARCHAR(120) NOT NULL,
  CREATED_AT  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UPDATED_AT  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY UQ_ESPORTS_GAMES_SLUG (SLUG)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE NEWS_CATEGORIES (
  ID          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  NAME        VARCHAR(100) NOT NULL,
  SLUG        VARCHAR(120) NOT NULL,
  CREATED_AT  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UPDATED_AT  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY UQ_NEWS_CATEGORIES_SLUG (SLUG)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- ================================================================
-- 003 — CATALOG (PRODUCTS, variants, inventory)
-- ================================================================
-- NOTE on PRODUCTS.MERCHANT_ID: that column and its foreign key are
-- added at the top of 004_merchants.sql, not here. It genuinely
-- depends on the `MERCHANTS` table (created in 004), and file order
-- (003 before 004) can't be changed without renumbering every file —
-- so, exactly like the original Marketplace_Migration.sql did, the
-- column is added via ALTER TABLE once its target exists. Every other
-- catalog column below is the current, final shape already.
-- ================================================================

-- Added 2026-09-17 — what KIND of product this is within its category
-- (Single Card, Booster Box, ... under Trading Card Games), a distinct
-- axis from PRODUCTS.TCG_GAME_ID (which game) and PRODUCT_CATEGORIES
-- (commerce category). Scoped per CATEGORY_ID rather than being a global
-- list — deliberately, so a future category (Gunpla grades, Computer
-- Parts component types, ...) can get its own rows with zero schema
-- change, instead of one flat enum or per-type boolean columns on
-- PRODUCTS (IS_BOOSTER_BOX, IS_SINGLE_CARD, ...) that wouldn't scale past
-- Trading Card Games. SLUG (not a separate CODE column) is the stable
-- value application logic matches against — same convention as
-- TCG_GAMES/PRODUCT_CATEGORIES already use.
CREATE TABLE PRODUCT_TYPES (
  ID           INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  CATEGORY_ID  INT UNSIGNED NOT NULL,
  NAME         VARCHAR(100) NOT NULL,
  SLUG         VARCHAR(120) NOT NULL,
  SORT_ORDER   INT UNSIGNED NOT NULL DEFAULT 0,
  STATUS       VARCHAR(20)  NOT NULL DEFAULT 'active',           -- 'active' | 'inactive' — app-validated
  CREATED_AT   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UPDATED_AT   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT FK_PRODUCT_TYPES_CATEGORY
    FOREIGN KEY (CATEGORY_ID) REFERENCES PRODUCT_CATEGORIES(ID) ON DELETE CASCADE,
  UNIQUE KEY UQ_PRODUCT_TYPES_CATEGORY_SLUG (CATEGORY_ID, SLUG),
  INDEX IDX_PRODUCT_TYPES_CATEGORY (CATEGORY_ID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE PRODUCTS (
  ID                INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  VENDOR_ID         INT UNSIGNED NOT NULL,
  CATEGORY_ID       INT UNSIGNED NOT NULL,
  TCG_GAME_ID       INT UNSIGNED NULL,                           -- only set when CATEGORY_ID is a TCG-related CATEGORY
  PRODUCT_TYPE_ID   INT UNSIGNED NULL,                           -- added 2026-09-17 — e.g. Single Card / Booster Box; only set when PRODUCT_TYPES has rows for CATEGORY_ID (see resolveProductTypeRequirement() in product.controller.js)
  NAME              VARCHAR(150) NOT NULL,
  SLUG              VARCHAR(180) NOT NULL,
  CODE              VARCHAR(100) NULL,                            -- SKU
  DESCRIPTION       LONGTEXT NULL,
  SHORT_DESCRIPTION VARCHAR(500) NULL,
  BRAND             VARCHAR(100) NULL,
  CONDITION_LABEL   VARCHAR(50) NULL,
  PRICE             DECIMAL(10,2) NOT NULL,
  STOCK_QUANTITY    INT UNSIGNED NOT NULL DEFAULT 0,               -- current stock; single source of truth (see INVENTORY_MOVEMENTS)
  LOW_STOCK_THRESHOLD INT UNSIGNED NULL,
  STATUS            VARCHAR(20) NOT NULL DEFAULT 'active',        -- 'active' | 'archived' | 'draft' | 'out_of_stock' — app-validated
  FEATURED          TINYINT(1) NOT NULL DEFAULT 0,
  WEIGHT_GRAMS      INT UNSIGNED NULL,
  TAGS              VARCHAR(255) NULL,
  CREATED_AT        TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UPDATED_AT        TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT FK_PRODUCTS_VENDOR
    FOREIGN KEY (VENDOR_ID) REFERENCES USERS(ID) ON DELETE RESTRICT,
  CONSTRAINT FK_PRODUCTS_CATEGORY
    FOREIGN KEY (CATEGORY_ID) REFERENCES PRODUCT_CATEGORIES(ID) ON DELETE RESTRICT,
  CONSTRAINT FK_PRODUCTS_TCG_GAME
    FOREIGN KEY (TCG_GAME_ID) REFERENCES TCG_GAMES(ID) ON DELETE SET NULL,
  CONSTRAINT FK_PRODUCTS_PRODUCT_TYPE
    FOREIGN KEY (PRODUCT_TYPE_ID) REFERENCES PRODUCT_TYPES(ID) ON DELETE SET NULL,
  UNIQUE KEY UQ_PRODUCTS_SLUG (SLUG),
  INDEX IDX_PRODUCTS_VENDOR (VENDOR_ID),
  INDEX IDX_PRODUCTS_CATEGORY (CATEGORY_ID),
  INDEX IDX_PRODUCTS_TCG_GAME (TCG_GAME_ID),
  INDEX IDX_PRODUCTS_PRODUCT_TYPE (PRODUCT_TYPE_ID),
  INDEX IDX_PRODUCTS_CODE (CODE)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- VENDOR_ID uses ON DELETE RESTRICT: a vendor account can't be hard-deleted
-- while it still owns PRODUCTS (and, transitively, inventory history) —
-- archive the vendor (USERS.STATUS = 'deleted') instead.

CREATE TABLE PRODUCT_IMAGES (
  ID          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  PRODUCT_ID  INT UNSIGNED NOT NULL,
  IMAGE_URL   LONGTEXT NOT NULL,
  SORT_ORDER  INT UNSIGNED NOT NULL DEFAULT 0,
  IS_PRIMARY  TINYINT(1) NOT NULL DEFAULT 0,
  CREATED_AT  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT FK_PRODUCT_IMAGES_PRODUCT
    FOREIGN KEY (PRODUCT_ID) REFERENCES PRODUCTS(ID) ON DELETE CASCADE,
  INDEX IDX_PRODUCT_IMAGES_PRODUCT (PRODUCT_ID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Product variants: simple, standard model. An option is a named axis
-- (e.g. "Colour"), an option VALUE is one choice on that axis (e.g.
-- "Red"), a variant is one concrete SKU-able combination, linked to
-- the option values that make it up.
--
-- STATUS: DORMANT / RESERVED FOR PLANNED FEATURE (PRODUCT_OPTIONS,
-- PRODUCT_OPTION_VALUES, PRODUCT_VARIANT_OPTION_VALUES) — schema-complete,
-- zero backend or frontend references as of this audit (2026-09-14).
-- PRODUCT_VARIANTS itself IS read by cart/checkout (defensively handles
-- a VARIANT_ID if one is ever set) but has no creation path in the
-- merchant product-management backend yet. Keep these tables; remove
-- only if this feature is formally abandoned.

CREATE TABLE PRODUCT_OPTIONS (
  ID          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  PRODUCT_ID  INT UNSIGNED NOT NULL,
  NAME        VARCHAR(50) NOT NULL,                     -- e.g. 'Colour', 'Size', 'Language'
  SORT_ORDER  INT UNSIGNED NOT NULL DEFAULT 0,
  CREATED_AT  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT FK_PRODUCT_OPTIONS_PRODUCT
    FOREIGN KEY (PRODUCT_ID) REFERENCES PRODUCTS(ID) ON DELETE CASCADE,
  UNIQUE KEY UQ_PRODUCT_OPTIONS_PRODUCT_NAME (PRODUCT_ID, NAME),
  INDEX IDX_PRODUCT_OPTIONS_PRODUCT (PRODUCT_ID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE PRODUCT_OPTION_VALUES (
  ID         INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  OPTION_ID  INT UNSIGNED NOT NULL,
  VALUE      VARCHAR(100) NOT NULL,                     -- e.g. 'Red', 'M', 'Japanese'
  SORT_ORDER INT UNSIGNED NOT NULL DEFAULT 0,
  CREATED_AT TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT FK_PRODUCT_OPTION_VALUES_OPTION
    FOREIGN KEY (OPTION_ID) REFERENCES PRODUCT_OPTIONS(ID) ON DELETE CASCADE,
  UNIQUE KEY UQ_PRODUCT_OPTION_VALUES_OPTION_VALUE (OPTION_ID, VALUE),
  INDEX IDX_PRODUCT_OPTION_VALUES_OPTION (OPTION_ID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE PRODUCT_VARIANTS (
  ID              INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  PRODUCT_ID      INT UNSIGNED NOT NULL,
  SKU             VARCHAR(100) NULL,
  PRICE_OVERRIDE  DECIMAL(10,2) NULL,                   -- NULL = use PRODUCTS.PRICE
  STOCK_QUANTITY  INT UNSIGNED NOT NULL DEFAULT 0,       -- single source of truth for THIS variant
  STATUS          VARCHAR(20) NOT NULL DEFAULT 'active', -- active | archived
  CREATED_AT      TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UPDATED_AT      TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT FK_PRODUCT_VARIANTS_PRODUCT
    FOREIGN KEY (PRODUCT_ID) REFERENCES PRODUCTS(ID) ON DELETE RESTRICT,
  UNIQUE KEY UQ_PRODUCT_VARIANTS_SKU (SKU),
  INDEX IDX_PRODUCT_VARIANTS_PRODUCT (PRODUCT_ID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE PRODUCT_VARIANT_OPTION_VALUES (
  ID               INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  VARIANT_ID       INT UNSIGNED NOT NULL,
  OPTION_VALUE_ID  INT UNSIGNED NOT NULL,
  CONSTRAINT FK_PVOV_VARIANT
    FOREIGN KEY (VARIANT_ID) REFERENCES PRODUCT_VARIANTS(ID) ON DELETE CASCADE,
  CONSTRAINT FK_PVOV_OPTION_VALUE
    FOREIGN KEY (OPTION_VALUE_ID) REFERENCES PRODUCT_OPTION_VALUES(ID) ON DELETE RESTRICT,
  UNIQUE KEY UQ_PVOV_VARIANT_OPTION_VALUE (VARIANT_ID, OPTION_VALUE_ID),
  INDEX IDX_PVOV_OPTION_VALUE (OPTION_VALUE_ID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE INVENTORY_MOVEMENTS (
  ID          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  PRODUCT_ID  INT UNSIGNED NOT NULL,
  VARIANT_ID  INT UNSIGNED NULL,                                 -- NULL = movement applies to the base product
  DELTA       INT NOT NULL,                                      -- signed: positive (restock) or negative (sale/adjustment)
  REASON      VARCHAR(100) NULL,
  CREATED_AT  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT FK_INVENTORY_MOVEMENTS_PRODUCT
    FOREIGN KEY (PRODUCT_ID) REFERENCES PRODUCTS(ID) ON DELETE RESTRICT,
  CONSTRAINT FK_INVENTORY_MOVEMENTS_VARIANT
    FOREIGN KEY (VARIANT_ID) REFERENCES PRODUCT_VARIANTS(ID) ON DELETE SET NULL,
  INDEX IDX_INVENTORY_MOVEMENTS_PRODUCT (PRODUCT_ID),
  INDEX IDX_INVENTORY_MOVEMENTS_VARIANT (VARIANT_ID),
  INDEX IDX_INVENTORY_MOVEMENTS_CREATED_AT (CREATED_AT)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- ON DELETE RESTRICT (not CASCADE): a product with recorded stock history
-- can never be physically deleted — set PRODUCTS.STATUS = 'archived'
-- instead. BACKEND REQUIREMENT: every write that changes
-- PRODUCTS.STOCK_QUANTITY / PRODUCT_VARIANTS.STOCK_QUANTITY must, in the
-- same transaction, also insert the matching INVENTORY_MOVEMENTS row.
-- ================================================================
-- 004 — MERCHANTS
-- ================================================================
-- A "merchant" is a business profile layered on top of the existing
-- USERS/JWT auth system — it does NOT introduce a parallel auth
-- system. Merchant staff authenticate through the same
-- POST /api/auth/login as everyone else. MERCHANT_USERS links an
-- existing USERS row to a merchant with a ROLE. Identity for "which
-- merchant is this request acting on behalf of" must always be
-- resolved server-side from MERCHANT_USERS for the authenticated
-- user — never accepted from the client.
-- ================================================================

-- PRODUCTS.MERCHANT_ID genuinely depends on this file's `MERCHANTS`
-- table, so it's added here rather than in 003_catalog.sql — see the
-- NOTE at the top of that file. Nullable and additive: a product with
-- MERCHANT_ID = NULL is a standalone vendor's product, scoped by
-- VENDOR_ID instead (dual-scoping model, both paths are live).
ALTER TABLE PRODUCTS
  ADD COLUMN MERCHANT_ID INT UNSIGNED NULL AFTER VENDOR_ID;

-- WHATSAPP_PHONE / WHATSAPP_NOTIFICATIONS_ENABLED added in migrations/0005
-- (WhatsApp Merchant Notifications, 2026-09-16) — see
-- Backend/services/notifications/. Deliberately separate from PHONE: PHONE
-- is general contact info (not necessarily E.164, not opt-in); a merchant's
-- WhatsApp notification number must be explicitly configured, never assumed
-- to be their login/contact phone. ENABLED defaults to 0 — opt-in only,
-- never on by default for existing or new merchants.
CREATE TABLE MERCHANTS (
  ID                  INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  BUSINESS_NAME       VARCHAR(150) NOT NULL,
  DISPLAY_NAME        VARCHAR(150) NOT NULL,
  SLUG                VARCHAR(180) NOT NULL,
  CONTACT_PERSON      VARCHAR(100) NOT NULL,
  EMAIL               VARCHAR(100) NOT NULL,
  PHONE               VARCHAR(20)  NULL,
  BUSINESS_CATEGORY   VARCHAR(50)  NULL,               -- e.g. 'tcg' | 'collectibles' | 'gunpla' | 'drone' | 'computer_parts' | 'general' — app-validated
  STATUS              VARCHAR(20)  NOT NULL DEFAULT 'PENDING', -- PENDING | ACTIVE | SUSPENDED | BANNED | REJECTED — see Database/README.md "Status conventions"
  COMMISSION_PERCENT  DECIMAL(5,2) NULL,                -- override; NULL = use PLATFORM_SETTINGS.platform_commission_percent
  SOCIAL_LINKS        TEXT NULL,                        -- JSON-encoded, app-validated
  WHATSAPP_PHONE                  VARCHAR(20)  NULL,     -- E.164 (e.g. +6738888888); distinct from PHONE, see note above
  WHATSAPP_NOTIFICATIONS_ENABLED  TINYINT(1)   NOT NULL DEFAULT 0,
  CREATED_AT          TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UPDATED_AT          TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY UQ_MERCHANTS_SLUG (SLUG),
  UNIQUE KEY UQ_MERCHANTS_EMAIL (EMAIL),
  INDEX IDX_MERCHANTS_STATUS (STATUS)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- New MERCHANTS default to PENDING and must not receive unrestricted
-- marketplace access until an admin sets STATUS = 'ACTIVE' (see
-- Backend/routes/api/admin.routes.js, Backend/modules/orderStateMachine.module.js
-- MERCHANT_TRANSITIONS: PENDING->ACTIVE, PENDING->REJECTED, REJECTED->ACTIVE,
-- ACTIVE->SUSPENDED, ACTIVE->BANNED, SUSPENDED->ACTIVE, SUSPENDED->BANNED,
-- BANNED->ACTIVE (an explicit, audited unban — never automatic)). SUSPENDED
-- keeps read-only dashboard access for the merchant's own staff
-- (Backend/modules/restAuth.module.js requireMerchant's
-- allowReadOnlyWhenSuspended); BANNED has none, not even read-only.

ALTER TABLE PRODUCTS
  ADD CONSTRAINT FK_PRODUCTS_MERCHANT
    FOREIGN KEY (MERCHANT_ID) REFERENCES MERCHANTS(ID) ON DELETE SET NULL,
  ADD INDEX IDX_PRODUCTS_MERCHANT (MERCHANT_ID);

CREATE TABLE MERCHANT_USERS (
  ID           INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  MERCHANT_ID  INT UNSIGNED NOT NULL,
  USER_ID      INT UNSIGNED NOT NULL,
  ROLE         VARCHAR(20)  NOT NULL DEFAULT 'MERCHANT_OWNER', -- MERCHANT_OWNER | MERCHANT_ADMIN | MERCHANT_EMPLOYEE
  STATUS       VARCHAR(20)  NOT NULL DEFAULT 'active',         -- active | suspended | removed
  CREATED_AT   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UPDATED_AT   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT FK_MERCHANT_USERS_MERCHANT
    FOREIGN KEY (MERCHANT_ID) REFERENCES MERCHANTS(ID) ON DELETE CASCADE,
  CONSTRAINT FK_MERCHANT_USERS_USER
    FOREIGN KEY (USER_ID) REFERENCES USERS(ID) ON DELETE CASCADE,
  UNIQUE KEY UQ_MERCHANT_USERS_MERCHANT_USER (MERCHANT_ID, USER_ID),
  INDEX IDX_MERCHANT_USERS_USER (USER_ID),
  INDEX IDX_MERCHANT_USERS_MERCHANT (MERCHANT_ID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE MERCHANT_ADDRESSES (
  ID            INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  MERCHANT_ID   INT UNSIGNED NOT NULL,
  LABEL         VARCHAR(50)  NULL,                      -- e.g. 'Pickup Point', 'Warehouse'
  ADDRESS_LINE1 VARCHAR(255) NOT NULL,
  DISTRICT      VARCHAR(100) NULL,
  MUKIM         VARCHAR(100) NULL,
  VILLAGE       VARCHAR(100) NULL,
  POSTCODE      VARCHAR(20)  NULL,
  COUNTRY_CODE  CHAR(2)      NOT NULL DEFAULT 'BN',
  IS_DEFAULT    TINYINT(1)   NOT NULL DEFAULT 0,
  CREATED_AT    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UPDATED_AT    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT FK_MERCHANT_ADDRESSES_MERCHANT
    FOREIGN KEY (MERCHANT_ID) REFERENCES MERCHANTS(ID) ON DELETE CASCADE,
  INDEX IDX_MERCHANT_ADDRESSES_MERCHANT (MERCHANT_ID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Bank details: encrypted-at-rest columns are the current, live shape
-- (as of migrations/0001 applied 2026-09-14). `ACCOUNT_NUMBER` (plaintext)
-- is DEPRECATED and kept only for backward compatibility with rows
-- inserted before encryption existed — application CODE must never write
-- to it going forward, and it is intentionally NOT dropped here (no
-- destructive change bundled into this schema rewrite — see
-- Database/README.md). API responses must only ever return
-- ACCOUNT_NUMBER_LAST4, never the ciphertext columns or a decrypted VALUE.
--
-- DISPLAY_NAME / NOTES / BANK_OTHER_LABEL added in migrations/0004 (Merchant
-- Payments Stage 1, 2026-09-16) — see Backend/modules/merchantPayments.module.js
-- for the app-validated BANK_NAME vocabulary (BIBD | BAIDURI | TAIB | OTHER).
-- ACCOUNT_NAME is the legal/bank-registered account holder name; DISPLAY_NAME
-- is the customer-facing recognizable name (e.g. a merchant's storefront
-- name) shown at checkout — they are deliberately separate fields, since a
-- merchant's bank account is rarely opened under their storefront name.
-- This table is also, unchanged, the source for existing platform→merchant
-- payout details — see Database/README.md "Merchant Payments" for how the
-- two concerns (customer→merchant bank transfer vs. platform→merchant
-- payout) share this one secure account record without being conflated.
CREATE TABLE MERCHANT_BANK_DETAILS (
  ID                          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  MERCHANT_ID                 INT UNSIGNED NOT NULL,
  BANK_NAME                   VARCHAR(150) NOT NULL,      -- app-validated: BIBD | BAIDURI | TAIB | OTHER
  BANK_OTHER_LABEL            VARCHAR(100) NULL,           -- free-text label, only meaningful/used when BANK_NAME = 'OTHER'
  DISPLAY_NAME                VARCHAR(150) NULL,           -- customer-facing name shown at checkout; falls back to ACCOUNT_NAME in application code when NULL
  ACCOUNT_NAME                VARCHAR(150) NOT NULL,       -- legal/bank account holder name
  ACCOUNT_NUMBER              VARCHAR(50)  NULL,          -- DEPRECATED plaintext column — do not write to this
  ACCOUNT_NUMBER_CIPHERTEXT   VARBINARY(255) NULL,        -- AES-256-GCM ciphertext, see Backend/modules/encryption.module.js
  ACCOUNT_NUMBER_IV           VARBINARY(16)  NULL,
  ACCOUNT_NUMBER_AUTH_TAG     VARBINARY(16)  NULL,
  ACCOUNT_NUMBER_LAST4        CHAR(4)        NULL,        -- safe to return in API responses
  SWIFT_CODE                  VARCHAR(20)  NULL,
  CURRENCY                    CHAR(3)      NOT NULL DEFAULT 'BND',
  NOTES                       VARCHAR(255) NULL,
  IS_DEFAULT                  TINYINT(1)   NOT NULL DEFAULT 0,
  CREATED_AT                  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UPDATED_AT                  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT FK_MERCHANT_BANK_DETAILS_MERCHANT
    FOREIGN KEY (MERCHANT_ID) REFERENCES MERCHANTS(ID) ON DELETE CASCADE,
  INDEX IDX_MERCHANT_BANK_DETAILS_MERCHANT (MERCHANT_ID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- One-default-per-merchant is an application-enforced invariant (unset the
-- previous default, then set the new one, inside one transaction — see
-- Backend/routes/api/merchant.routes.js), not a DB constraint — this schema
-- avoids partial-unique-index tricks per "Supported engine" in
-- Database/README.md (no CHECK constraints assumed available).
-- ================================================================
-- 005 — ORDERS / CHECKOUT
-- ================================================================
-- One customer order (ORDERS) can contain items from multiple
-- MERCHANTS. Each merchant's slice is a merchant_order — this is
-- what a merchant's dashboard/API can see and act on. Customers see
-- the whole `ORDERS` row; MERCHANTS only ever see their own
-- `MERCHANT_ORDERS` row and its `ORDER_ITEMS`.
--
-- ORDERS, MERCHANT_ORDERS, and ORDER_ITEMS are financial/fulfillment
-- records and are never hard-deleted by application CODE — every FK
-- into them below uses ON DELETE RESTRICT for that REASON.
-- ================================================================

CREATE TABLE CUSTOMER_ADDRESSES (
  ID                    INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  USER_ID               INT UNSIGNED NOT NULL,
  LABEL                 VARCHAR(50)  NULL,
  RECIPIENT_NAME        VARCHAR(100) NOT NULL,
  PHONE                 VARCHAR(20)  NULL,
  ADDRESS_LINE1         VARCHAR(255) NOT NULL,
  ADDRESS_LINE2         VARCHAR(255) NULL,                -- added 2026-09-19 (customer delivery checkout) — unit/floor/building, optional
  DISTRICT              VARCHAR(100) NULL,
  MUKIM                 VARCHAR(100) NULL,
  VILLAGE               VARCHAR(100) NULL,
  POSTCODE              VARCHAR(20)  NULL,
  COUNTRY_CODE          CHAR(2)      NOT NULL DEFAULT 'BN',
  IS_DEFAULT_SHIPPING   TINYINT(1)   NOT NULL DEFAULT 0,
  IS_DEFAULT_BILLING    TINYINT(1)   NOT NULL DEFAULT 0,
  CREATED_AT            TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UPDATED_AT            TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT FK_CUSTOMER_ADDRESSES_USER
    FOREIGN KEY (USER_ID) REFERENCES USERS(ID) ON DELETE CASCADE,
  INDEX IDX_CUSTOMER_ADDRESSES_USER (USER_ID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE CARTS (
  ID          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  USER_ID     INT UNSIGNED NULL,                        -- NULL for a guest cart
  GUEST_TOKEN CHAR(36)     NULL,                         -- app-generated UUID, stored client-side, for guest CARTS
  STATUS      VARCHAR(20)  NOT NULL DEFAULT 'active',    -- active | converted | abandoned
  CREATED_AT  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UPDATED_AT  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT FK_CARTS_USER
    FOREIGN KEY (USER_ID) REFERENCES USERS(ID) ON DELETE CASCADE,
  UNIQUE KEY UQ_CARTS_USER (USER_ID),          -- MySQL does not enforce uniqueness among NULLs, so this never blocks multiple guest CARTS
  UNIQUE KEY UQ_CARTS_GUEST_TOKEN (GUEST_TOKEN),
  INDEX IDX_CARTS_STATUS (STATUS)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE CART_ITEMS (
  ID          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  CART_ID     INT UNSIGNED NOT NULL,
  PRODUCT_ID  INT UNSIGNED NOT NULL,
  VARIANT_ID  INT UNSIGNED NULL,
  VARIANT_KEY INT UNSIGNED GENERATED ALWAYS AS (COALESCE(VARIANT_ID, 0)) STORED, -- lets the unique key below treat "no variant" as one consistent VALUE
  QUANTITY    INT UNSIGNED NOT NULL,
  CREATED_AT  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UPDATED_AT  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT FK_CART_ITEMS_CART
    FOREIGN KEY (CART_ID) REFERENCES CARTS(ID) ON DELETE CASCADE,
  CONSTRAINT FK_CART_ITEMS_PRODUCT
    FOREIGN KEY (PRODUCT_ID) REFERENCES PRODUCTS(ID) ON DELETE CASCADE,
  CONSTRAINT FK_CART_ITEMS_VARIANT
    FOREIGN KEY (VARIANT_ID) REFERENCES PRODUCT_VARIANTS(ID) ON DELETE CASCADE,
  UNIQUE KEY UQ_CART_ITEMS_CART_PRODUCT_VARIANT (CART_ID, PRODUCT_ID, VARIANT_KEY),
  INDEX IDX_CART_ITEMS_CART (CART_ID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- Cart pricing is NEVER read from this table at checkout time — checkout
-- always recomputes PRICE/SUBTOTAL/discount/shipping/total from current DB values.

CREATE TABLE SHIPPING_METHODS (
  ID           INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  NAME         VARCHAR(100) NOT NULL,
  CODE         VARCHAR(30)  NOT NULL,                   -- 'pickup' | 'local_delivery' | 'courier' | 'international' — app-validated
  DESCRIPTION  VARCHAR(255) NULL,
  BASE_FEE     DECIMAL(10,2) NOT NULL DEFAULT 0,
  STATUS       VARCHAR(20)  NOT NULL DEFAULT 'active',
  CREATED_AT   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UPDATED_AT   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY UQ_SHIPPING_METHODS_CODE (CODE)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- CODE = 'pickup' is the only code Backend/modules/fulfilment.module.js
-- treats as fulfilment type PICKUP; every other code is DELIVERY. A row's
-- CODE, not its NAME, is what checkout eligibility keys off.

-- Per-merchant fulfilment enablement — added alongside offline payment
-- methods (Pay on Delivery / Pay on Pickup) so eligibility for both can be
-- computed the same way: added 2026-09-18, mirrors MERCHANT_PAYMENT_METHODS
-- (004_merchants.sql-era design, see 010_merchant_payments.sql) exactly,
-- including the "no row = disabled" convention. Nanashi is multi-merchant —
-- one merchant may not offer delivery while another does, so this is
-- deliberately per-merchant, not a single global on/off toggle.
CREATE TABLE MERCHANT_FULFILMENT_METHODS (
  ID           INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  MERCHANT_ID  INT UNSIGNED NOT NULL,
  METHOD       VARCHAR(20)  NOT NULL,                    -- app-validated: DELIVERY | PICKUP — see Backend/modules/fulfilment.module.js
  ENABLED      TINYINT(1)   NOT NULL DEFAULT 0,
  CREATED_AT   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UPDATED_AT   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT FK_MERCHANT_FULFILMENT_METHODS_MERCHANT
    FOREIGN KEY (MERCHANT_ID) REFERENCES MERCHANTS(ID) ON DELETE CASCADE,
  UNIQUE KEY UQ_MERCHANT_FULFILMENT_METHODS_MERCHANT_METHOD (MERCHANT_ID, METHOD),
  INDEX IDX_MERCHANT_FULFILMENT_METHODS_MERCHANT (MERCHANT_ID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- No row for a given (MERCHANT_ID, METHOD) means "not configured / not
-- enabled" — application code must treat a missing row the same as
-- ENABLED = 0, never assume a method is on by default.

CREATE TABLE COUPONS (
  ID                    INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  CODE                  VARCHAR(50) NOT NULL,
  DESCRIPTION           VARCHAR(255) NULL,
  DISCOUNT_TYPE         VARCHAR(20) NOT NULL,             -- 'percent' | 'fixed'
  DISCOUNT_VALUE        DECIMAL(10,2) NOT NULL,
  MIN_SUBTOTAL          DECIMAL(10,2) NULL,
  MAX_USES              INT UNSIGNED NULL,
  MAX_USES_PER_USER     INT UNSIGNED NULL,
  STARTS_AT             TIMESTAMP NULL,
  ENDS_AT               TIMESTAMP NULL,
  STATUS                VARCHAR(20) NOT NULL DEFAULT 'active',
  CREATED_AT            TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UPDATED_AT            TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY UQ_COUPONS_CODE (CODE)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- MAX_USES / MAX_USES_PER_USER are enforced in application logic (count
-- rows in COUPON_USAGE below), not as DB constraints.

CREATE TABLE ORDERS (
  ID                    INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  ORDER_NUMBER          VARCHAR(30)  NOT NULL,            -- app-generated after insert, e.g. 'NC00001'
  USER_ID               INT UNSIGNED NOT NULL,
  SHIPPING_ADDRESS_ID   INT UNSIGNED NULL,
  BILLING_ADDRESS_ID    INT UNSIGNED NULL,
  SHIPPING_METHOD_ID    INT UNSIGNED NULL,
  COUPON_ID             INT UNSIGNED NULL,
  DELIVERY_INSTRUCTIONS VARCHAR(500) NULL,                -- added 2026-09-19 — customer-entered, one-time per order (not part of the reusable CUSTOMER_ADDRESSES row); only meaningful when the resolved fulfilment type is DELIVERY, but not enforced NULL for Pickup at the DB level (app-validated, see checkout.routes.js)
  SUBTOTAL              DECIMAL(10,2) NOT NULL,
  DISCOUNT_TOTAL        DECIMAL(10,2) NOT NULL DEFAULT 0,
  SHIPPING_TOTAL        DECIMAL(10,2) NOT NULL DEFAULT 0,
  GRAND_TOTAL           DECIMAL(10,2) NOT NULL,
  CURRENCY              CHAR(3) NOT NULL DEFAULT 'BND',
  PAYMENT_STATUS        VARCHAR(20) NOT NULL DEFAULT 'PENDING',        -- PENDING | AUTHORIZED | PAID | FAILED | CANCELLED | REFUNDED | PARTIALLY_REFUNDED
  STATUS                VARCHAR(20) NOT NULL DEFAULT 'PENDING_PAYMENT', -- PENDING_PAYMENT | PAID | PROCESSING | READY | SHIPPED | DELIVERED | CANCELLED | REFUNDED
  PLACED_AT             TIMESTAMP NULL,
  CREATED_AT            TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UPDATED_AT            TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT FK_ORDERS_USER
    FOREIGN KEY (USER_ID) REFERENCES USERS(ID) ON DELETE RESTRICT,
  CONSTRAINT FK_ORDERS_SHIPPING_ADDRESS
    FOREIGN KEY (SHIPPING_ADDRESS_ID) REFERENCES CUSTOMER_ADDRESSES(ID) ON DELETE SET NULL,
  CONSTRAINT FK_ORDERS_BILLING_ADDRESS
    FOREIGN KEY (BILLING_ADDRESS_ID) REFERENCES CUSTOMER_ADDRESSES(ID) ON DELETE SET NULL,
  CONSTRAINT FK_ORDERS_SHIPPING_METHOD
    FOREIGN KEY (SHIPPING_METHOD_ID) REFERENCES SHIPPING_METHODS(ID) ON DELETE SET NULL,
  CONSTRAINT FK_ORDERS_COUPON
    FOREIGN KEY (COUPON_ID) REFERENCES COUPONS(ID) ON DELETE SET NULL,
  UNIQUE KEY UQ_ORDERS_ORDER_NUMBER (ORDER_NUMBER),
  INDEX IDX_ORDERS_USER (USER_ID),
  INDEX IDX_ORDERS_STATUS (STATUS),
  INDEX IDX_ORDERS_PAYMENT_STATUS (PAYMENT_STATUS),
  INDEX IDX_ORDERS_CREATED_AT (CREATED_AT)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- Orders always belong to a registered user — guest CARTS are supported,
-- but checkout requires an authenticated account. Guest checkout is a
-- possible future extension, not implemented.

-- Added 2026-09-19 (customer delivery checkout). One optional reference photo
-- per order — "where to leave it" (front gate, reception, etc.), never a
-- product photo. Scoped to ORDER_ID, not MERCHANT_ORDER_ID: fulfilment
-- (shipping method + address + instructions + this photo) is chosen ONCE per
-- checkout for the whole cart under the current "one shipping method per
-- order" model (ORDERS.SHIPPING_METHOD_ID, not per-merchant-order) — see the
-- checkout.routes.js header comment. If fulfilment ever becomes genuinely
-- per-merchant, this table's scope would need to move with it; it does not
-- today. FILE_URL is always a backend-relative path under
-- /public/uploads/delivery-references/ (validated server-side, see
-- checkout.routes.js) — never a client-supplied arbitrary URL, and never a
-- base64 blob stored in the database.
CREATE TABLE ORDER_DELIVERY_ATTACHMENTS (
  ID           INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  ORDER_ID     INT UNSIGNED NOT NULL,
  FILE_URL     VARCHAR(255) NOT NULL,
  FILE_TYPE    VARCHAR(30)  NOT NULL,                     -- the validated MIME type at upload time, e.g. 'image/jpeg'
  CREATED_AT   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT FK_ORDER_DELIVERY_ATTACHMENTS_ORDER
    FOREIGN KEY (ORDER_ID) REFERENCES ORDERS(ID) ON DELETE CASCADE,
  UNIQUE KEY UQ_ORDER_DELIVERY_ATTACHMENTS_ORDER (ORDER_ID) -- one reference photo per order for now, per product spec
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE MERCHANT_ORDERS (
  ID                     INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  MERCHANT_ORDER_NUMBER  VARCHAR(40)  NOT NULL,          -- app-generated after insert, e.g. 'MO000001'
  ORDER_ID               INT UNSIGNED NOT NULL,
  MERCHANT_ID            INT UNSIGNED NOT NULL,
  SUBTOTAL               DECIMAL(10,2) NOT NULL,
  COMMISSION_PERCENT     DECIMAL(5,2)  NOT NULL,         -- snapshot at order time — never recompute later from MERCHANTS.COMMISSION_PERCENT
  COMMISSION_AMOUNT      DECIMAL(10,2) NOT NULL,
  MERCHANT_NET_AMOUNT    DECIMAL(10,2) NOT NULL,
  STATUS                 VARCHAR(20) NOT NULL DEFAULT 'PROCESSING', -- PROCESSING | READY | SHIPPED | DELIVERED | CANCELLED
  CREATED_AT             TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UPDATED_AT             TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT FK_MERCHANT_ORDERS_ORDER
    FOREIGN KEY (ORDER_ID) REFERENCES ORDERS(ID) ON DELETE RESTRICT,
  CONSTRAINT FK_MERCHANT_ORDERS_MERCHANT
    FOREIGN KEY (MERCHANT_ID) REFERENCES MERCHANTS(ID) ON DELETE RESTRICT,
  UNIQUE KEY UQ_MERCHANT_ORDERS_NUMBER (MERCHANT_ORDER_NUMBER),
  INDEX IDX_MERCHANT_ORDERS_ORDER (ORDER_ID),
  INDEX IDX_MERCHANT_ORDERS_MERCHANT (MERCHANT_ID),
  INDEX IDX_MERCHANT_ORDERS_STATUS (STATUS)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- A merchant's REST session must only ever SELECT rows here WHERE
-- MERCHANT_ID = <resolved server-side from MERCHANT_USERS>. Never accept
-- MERCHANT_ID from the client.

CREATE TABLE ORDER_ITEMS (
  ID                      INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  ORDER_ID                INT UNSIGNED NOT NULL,
  MERCHANT_ORDER_ID       INT UNSIGNED NOT NULL,
  PRODUCT_ID              INT UNSIGNED NOT NULL,
  VARIANT_ID              INT UNSIGNED NULL,
  PRODUCT_NAME_SNAPSHOT   VARCHAR(150) NOT NULL,          -- product NAME/PRICE can change after purchase; the order must not depend on current product data
  SKU_SNAPSHOT            VARCHAR(100) NULL,
  UNIT_PRICE_SNAPSHOT     DECIMAL(10,2) NOT NULL,
  QUANTITY                INT UNSIGNED NOT NULL,
  LINE_TOTAL              DECIMAL(10,2) NOT NULL,
  CREATED_AT              TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT FK_ORDER_ITEMS_ORDER
    FOREIGN KEY (ORDER_ID) REFERENCES ORDERS(ID) ON DELETE RESTRICT,
  CONSTRAINT FK_ORDER_ITEMS_MERCHANT_ORDER
    FOREIGN KEY (MERCHANT_ORDER_ID) REFERENCES MERCHANT_ORDERS(ID) ON DELETE RESTRICT,
  CONSTRAINT FK_ORDER_ITEMS_PRODUCT
    FOREIGN KEY (PRODUCT_ID) REFERENCES PRODUCTS(ID) ON DELETE RESTRICT,
  CONSTRAINT FK_ORDER_ITEMS_VARIANT
    FOREIGN KEY (VARIANT_ID) REFERENCES PRODUCT_VARIANTS(ID) ON DELETE RESTRICT,
  INDEX IDX_ORDER_ITEMS_ORDER (ORDER_ID),
  INDEX IDX_ORDER_ITEMS_MERCHANT_ORDER (MERCHANT_ORDER_ID),
  INDEX IDX_ORDER_ITEMS_PRODUCT (PRODUCT_ID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE ORDER_STATUS_HISTORY (
  ID                   INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  ORDER_ID             INT UNSIGNED NOT NULL,
  MERCHANT_ORDER_ID    INT UNSIGNED NULL,                -- set when the change is a merchant-order-level fulfillment update
  OLD_STATUS           VARCHAR(20) NULL,
  NEW_STATUS           VARCHAR(20) NOT NULL,
  CHANGED_BY_TYPE      VARCHAR(20) NOT NULL,              -- customer | merchant | admin | system
  CHANGED_BY_USER_ID   INT UNSIGNED NULL,
  NOTE                 TEXT NULL,
  CREATED_AT           TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT FK_ORDER_STATUS_HISTORY_ORDER
    FOREIGN KEY (ORDER_ID) REFERENCES ORDERS(ID) ON DELETE CASCADE,
  CONSTRAINT FK_ORDER_STATUS_HISTORY_MERCHANT_ORDER
    FOREIGN KEY (MERCHANT_ORDER_ID) REFERENCES MERCHANT_ORDERS(ID) ON DELETE CASCADE,
  CONSTRAINT FK_ORDER_STATUS_HISTORY_USER
    FOREIGN KEY (CHANGED_BY_USER_ID) REFERENCES USERS(ID) ON DELETE SET NULL,
  INDEX IDX_ORDER_STATUS_HISTORY_ORDER (ORDER_ID),
  INDEX IDX_ORDER_STATUS_HISTORY_MERCHANT_ORDER (MERCHANT_ORDER_ID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- CASCADE here is safe: ORDERS/MERCHANT_ORDERS are never hard-deleted by
-- application CODE, so this never actually fires in practice.

CREATE TABLE SHIPMENTS (
  ID                   INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  MERCHANT_ORDER_ID    INT UNSIGNED NOT NULL,
  SHIPPING_METHOD_ID   INT UNSIGNED NULL,
  CARRIER              VARCHAR(100) NULL,
  TRACKING_NUMBER      VARCHAR(100) NULL,
  STATUS               VARCHAR(20) NOT NULL DEFAULT 'PENDING', -- PENDING | SHIPPED | DELIVERED
  SHIPPED_AT           TIMESTAMP NULL,
  DELIVERED_AT         TIMESTAMP NULL,
  CREATED_AT           TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UPDATED_AT           TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT FK_SHIPMENTS_MERCHANT_ORDER
    FOREIGN KEY (MERCHANT_ORDER_ID) REFERENCES MERCHANT_ORDERS(ID) ON DELETE CASCADE,
  CONSTRAINT FK_SHIPMENTS_SHIPPING_METHOD
    FOREIGN KEY (SHIPPING_METHOD_ID) REFERENCES SHIPPING_METHODS(ID) ON DELETE SET NULL,
  UNIQUE KEY UQ_SHIPMENTS_MERCHANT_ORDER (MERCHANT_ORDER_ID), -- one shipment per merchant order for now
  INDEX IDX_SHIPMENTS_STATUS (STATUS)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE COUPON_USAGE (
  ID          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  COUPON_ID   INT UNSIGNED NOT NULL,
  USER_ID     INT UNSIGNED NOT NULL,
  ORDER_ID    INT UNSIGNED NOT NULL,
  USED_AT     TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT FK_COUPON_USAGE_COUPON
    FOREIGN KEY (COUPON_ID) REFERENCES COUPONS(ID) ON DELETE CASCADE,
  CONSTRAINT FK_COUPON_USAGE_USER
    FOREIGN KEY (USER_ID) REFERENCES USERS(ID) ON DELETE CASCADE,
  CONSTRAINT FK_COUPON_USAGE_ORDER
    FOREIGN KEY (ORDER_ID) REFERENCES ORDERS(ID) ON DELETE RESTRICT,
  INDEX IDX_COUPON_USAGE_COUPON_USER (COUPON_ID, USER_ID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Backs Backend/routes/api/checkout.routes.js. The UNIQUE key on
-- (USER_ID, IDEMPOTENCY_KEY) is what makes a duplicate checkout attempt
-- fail fast at the database level, even under real concurrency, before
-- any reservation/payment logic runs a second time.
CREATE TABLE CHECKOUT_IDEMPOTENCY (
  ID               INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  USER_ID          INT UNSIGNED NOT NULL,
  IDEMPOTENCY_KEY  VARCHAR(100) NOT NULL,
  REQUEST_HASH     CHAR(64)     NOT NULL,             -- sha256 of the normalized request payload
  STATUS           VARCHAR(20)  NOT NULL DEFAULT 'PROCESSING', -- PROCESSING | COMPLETED | FAILED
  ORDER_ID         INT UNSIGNED NULL,
  RESPONSE_JSON    LONGTEXT NULL,                       -- the exact { httpStatus, BODY } to replay on a retry
  CREATED_AT       TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  EXPIRES_AT       TIMESTAMP NOT NULL,
  CONSTRAINT FK_CHECKOUT_IDEMPOTENCY_USER
    FOREIGN KEY (USER_ID) REFERENCES USERS(ID) ON DELETE CASCADE,
  CONSTRAINT FK_CHECKOUT_IDEMPOTENCY_ORDER
    FOREIGN KEY (ORDER_ID) REFERENCES ORDERS(ID) ON DELETE SET NULL,
  UNIQUE KEY UQ_CHECKOUT_IDEMPOTENCY_USER_KEY (USER_ID, IDEMPOTENCY_KEY),
  INDEX IDX_CHECKOUT_IDEMPOTENCY_EXPIRES (EXPIRES_AT)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- EXPIRES_AT exists for a future cleanup job (DELETE WHERE EXPIRES_AT <
-- NOW()) — no such job is implemented yet; rows are harmless to leave in
-- place until one exists.
-- ================================================================
-- 006 — PAYMENTS
-- ================================================================

CREATE TABLE PAYMENT_TRANSACTIONS (
  ID                      INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  ORDER_ID                INT UNSIGNED NOT NULL,
  PROVIDER                VARCHAR(30) NOT NULL,          -- 'mock_cybersource' | 'cybersource' — matches PaymentService PROVIDER ids
  PROVIDER_TRANSACTION_ID VARCHAR(100) NULL,
  AMOUNT                  DECIMAL(10,2) NOT NULL,
  CURRENCY                CHAR(3) NOT NULL DEFAULT 'BND',
  STATUS                  VARCHAR(20) NOT NULL DEFAULT 'PENDING', -- PENDING | AUTHORIZED | PAID | FAILED | CANCELLED | REFUNDED | PARTIALLY_REFUNDED
  RAW_RESPONSE            LONGTEXT NULL,                  -- sanitized JSON only — never store raw PAN/CVV here or anywhere
  CREATED_AT              TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UPDATED_AT              TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT FK_PAYMENT_TRANSACTIONS_ORDER
    FOREIGN KEY (ORDER_ID) REFERENCES ORDERS(ID) ON DELETE RESTRICT,
  INDEX IDX_PAYMENT_TRANSACTIONS_ORDER (ORDER_ID),
  INDEX IDX_PAYMENT_TRANSACTIONS_STATUS (STATUS),
  INDEX IDX_PAYMENT_TRANSACTIONS_CREATED_AT (CREATED_AT)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- Each attempt (including retries) is its own row — doubles as the
-- payment-attempt log, so no separate payment_attempts table exists.

-- STATUS: DORMANT / RESERVED FOR PLANNED FEATURE — schema-complete,
-- zero backend query references as of this audit (2026-09-14).
-- Backend/services/payment/CyberSourceProvider.js explicitly documents
-- that automated REFUNDS are "not implemented yet" and tells admins to
-- "record via the REFUNDS table" manually. Keep; remove only if refund
-- automation is formally abandoned.
CREATE TABLE REFUNDS (
  ID                      INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  ORDER_ID                INT UNSIGNED NOT NULL,
  PAYMENT_TRANSACTION_ID  INT UNSIGNED NOT NULL,
  AMOUNT                  DECIMAL(10,2) NOT NULL,
  REASON                  VARCHAR(255) NULL,
  STATUS                  VARCHAR(20) NOT NULL DEFAULT 'PENDING', -- PENDING | PROCESSED | FAILED
  PROCESSED_BY_USER_ID    INT UNSIGNED NULL,
  CREATED_AT              TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UPDATED_AT              TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT FK_REFUNDS_ORDER
    FOREIGN KEY (ORDER_ID) REFERENCES ORDERS(ID) ON DELETE RESTRICT,
  CONSTRAINT FK_REFUNDS_PAYMENT_TRANSACTION
    FOREIGN KEY (PAYMENT_TRANSACTION_ID) REFERENCES PAYMENT_TRANSACTIONS(ID) ON DELETE RESTRICT,
  CONSTRAINT FK_REFUNDS_PROCESSED_BY
    FOREIGN KEY (PROCESSED_BY_USER_ID) REFERENCES USERS(ID) ON DELETE SET NULL,
  INDEX IDX_REFUNDS_ORDER (ORDER_ID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- ================================================================
-- 007 — CONTENT / COMMUNITY (TCG, esports, trading, NEWS, SERVICES, REVIEWS)
-- ================================================================

CREATE TABLE DECK_LISTS (
  ID           INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  TCG_GAME_ID  INT UNSIGNED NOT NULL,
  CREATED_BY   INT UNSIGNED NULL,
  NAME         VARCHAR(255) NOT NULL,
  ARCHETYPE    VARCHAR(100) NULL,
  FORMAT       VARCHAR(100) NULL,
  PILOT        VARCHAR(100) NULL,
  DESCRIPTION  TEXT NULL,
  KEY_CARDS    TEXT NULL,
  WIN_RATE     DECIMAL(5,2) NULL,
  POPULARITY   INT UNSIGNED NULL,
  AVG_COST     DECIMAL(10,2) NULL,
  FEATURED     TINYINT(1) NOT NULL DEFAULT 0,
  CREATED_AT   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UPDATED_AT   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT FK_DECK_LISTS_TCG_GAME
    FOREIGN KEY (TCG_GAME_ID) REFERENCES TCG_GAMES(ID) ON DELETE RESTRICT,
  CONSTRAINT FK_DECK_LISTS_CREATED_BY
    FOREIGN KEY (CREATED_BY) REFERENCES USERS(ID) ON DELETE SET NULL,
  INDEX IDX_DECK_LISTS_TCG_GAME (TCG_GAME_ID),
  INDEX IDX_DECK_LISTS_ARCHETYPE (ARCHETYPE),
  INDEX IDX_DECK_LISTS_FEATURED (FEATURED)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE TOURNAMENTS (
  ID                     INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  ESPORTS_GAME_ID        INT UNSIGNED NOT NULL,
  NAME                   VARCHAR(255) NOT NULL,
  SLUG                   VARCHAR(280) NOT NULL,
  DESCRIPTION            LONGTEXT NULL,
  LOCATION               VARCHAR(255) NULL,
  ENTRY_FEE              DECIMAL(10,2) NULL,
  ORGANIZER              VARCHAR(100) NULL,
  RULES                  LONGTEXT NULL,
  REGISTRATION_DEADLINE  TIMESTAMP NULL,
  REGISTRATION_TYPE      VARCHAR(20) NOT NULL DEFAULT 'individual', -- 'individual' | 'team'
  TEAM_SIZE              INT UNSIGNED NULL,                          -- required (app-level) when REGISTRATION_TYPE = 'team'
  MAX_ENTRIES            INT UNSIGNED NULL,                          -- max registrants (individual) OR max teams (team)
  STATUS                 VARCHAR(20) NOT NULL DEFAULT 'draft',       -- draft|open|closed|completed|cancelled
  START_DATE             TIMESTAMP NULL,
  END_DATE               TIMESTAMP NULL,
  CREATED_AT             TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UPDATED_AT             TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT FK_TOURNAMENTS_ESPORTS_GAME
    FOREIGN KEY (ESPORTS_GAME_ID) REFERENCES ESPORTS_GAMES(ID) ON DELETE RESTRICT,
  UNIQUE KEY UQ_TOURNAMENTS_SLUG (SLUG),
  INDEX IDX_TOURNAMENTS_ESPORTS_GAME (ESPORTS_GAME_ID),
  INDEX IDX_TOURNAMENTS_STATUS (STATUS),
  INDEX IDX_TOURNAMENTS_START_DATE (START_DATE)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE TOURNAMENT_REGISTRATIONS (
  ID             INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  TOURNAMENT_ID  INT UNSIGNED NOT NULL,
  USER_ID        INT UNSIGNED NULL,
  GUEST_NAME     VARCHAR(100) NULL,                                -- set when USER_ID IS NULL (guest participant)
  NICKNAME       VARCHAR(100) NULL,
  STATUS         VARCHAR(20) NOT NULL DEFAULT 'registered',        -- registered|checked_in|withdrawn|disqualified
  REGISTERED_AT  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT FK_REGISTRATIONS_TOURNAMENT
    FOREIGN KEY (TOURNAMENT_ID) REFERENCES TOURNAMENTS(ID) ON DELETE CASCADE,
  CONSTRAINT FK_REGISTRATIONS_USER
    FOREIGN KEY (USER_ID) REFERENCES USERS(ID) ON DELETE SET NULL,
  UNIQUE KEY UQ_REGISTRATIONS_TOURNAMENT_USER (TOURNAMENT_ID, USER_ID),
  UNIQUE KEY UQ_REGISTRATIONS_ID_TOURNAMENT (ID, TOURNAMENT_ID),        -- composite candidate key for TOURNAMENT_TEAMS/TOURNAMENT_TEAM_MEMBERS below
  INDEX IDX_REGISTRATIONS_TOURNAMENT (TOURNAMENT_ID),
  INDEX IDX_REGISTRATIONS_USER (USER_ID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE TOURNAMENT_TEAMS (
  ID                       INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  TOURNAMENT_ID            INT UNSIGNED NOT NULL,
  NAME                     VARCHAR(255) NOT NULL,
  CAPTAIN_REGISTRATION_ID  INT UNSIGNED NULL,
  STATUS                   VARCHAR(20) NOT NULL DEFAULT 'registered',
  CREATED_AT               TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UPDATED_AT               TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT FK_TEAMS_TOURNAMENT
    FOREIGN KEY (TOURNAMENT_ID) REFERENCES TOURNAMENTS(ID) ON DELETE CASCADE,
  -- Plain FK on CAPTAIN_REGISTRATION_ID only (not composite): the invariants
  -- "captain belongs to the tournament" and "captain is an actual member of
  -- THIS team" are enforced in backend service logic, not by MySQL — see
  -- Database/README.md.
  CONSTRAINT FK_TEAMS_CAPTAIN_REGISTRATION
    FOREIGN KEY (CAPTAIN_REGISTRATION_ID)
    REFERENCES TOURNAMENT_REGISTRATIONS(ID) ON DELETE SET NULL,
  UNIQUE KEY UQ_TEAMS_TOURNAMENT_NAME (TOURNAMENT_ID, NAME),
  UNIQUE KEY UQ_TEAMS_ID_TOURNAMENT (ID, TOURNAMENT_ID),           -- composite candidate key for TOURNAMENT_TEAM_MEMBERS below
  INDEX IDX_TEAMS_TOURNAMENT (TOURNAMENT_ID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE TOURNAMENT_TEAM_MEMBERS (
  ID               INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  TOURNAMENT_ID    INT UNSIGNED NOT NULL,                          -- redundant by design: lets both composite FKs below be enforced by MySQL itself
  TEAM_ID          INT UNSIGNED NOT NULL,
  REGISTRATION_ID  INT UNSIGNED NOT NULL,
  JOINED_AT        TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT FK_TEAM_MEMBERS_TEAM
    FOREIGN KEY (TEAM_ID, TOURNAMENT_ID)
    REFERENCES TOURNAMENT_TEAMS(ID, TOURNAMENT_ID) ON DELETE CASCADE,
  CONSTRAINT FK_TEAM_MEMBERS_REGISTRATION
    FOREIGN KEY (REGISTRATION_ID, TOURNAMENT_ID)
    REFERENCES TOURNAMENT_REGISTRATIONS(ID, TOURNAMENT_ID) ON DELETE CASCADE,
  UNIQUE KEY UQ_TEAM_MEMBERS_REGISTRATION (REGISTRATION_ID),       -- a registration belongs to at most one team, ever
  INDEX IDX_TEAM_MEMBERS_TEAM (TEAM_ID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- BACKEND REQUIREMENT (transactional): creating a team registration — the
-- team row, each member's registration row, each TOURNAMENT_TEAM_MEMBERS
-- row, and the captain assignment — must happen in a single DB transaction.

CREATE TABLE TRADE_LISTINGS (
